import {planCompany,planShopping} from './agent-adapter.mjs';
import {initialState} from './business-domain.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const contexts={company:{title:'¿Qué movemos hoy?',description:'Convierte tus prioridades en un plan para revisar.',placeholder:'Quiero optimizar los recursos de mi empresa…',prompts:['Optimizar recursos','Revisar pagos a proveedores','Controlar presupuesto']},shopping:{title:'Tu próxima compra, mejor pensada.',description:'Compara opciones sin perder de vista tu presupuesto.',placeholder:'Busco audífonos por menos de 170 USD…',prompts:['Comparar audífonos','Explorar productos','Revisar mis pedidos']},daily:{title:'Tu día a día, un poco más ligero.',description:'Dale un lugar a cada gasto y claridad a tus decisiones.',placeholder:'Quiero organizar mis gastos cotidianos…',prompts:['Registrar un gasto','Ver mis gastos','Exportar mis gastos']}};
let mode='company';
function changeMode(next){if(!contexts[next])return;mode=next;const c=contexts[mode];$('#context-title').textContent=c.title;$('#context-description').textContent=c.description;$('#intent').placeholder=c.placeholder;$('#intent').value='';$('#result-section').hidden=true;document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===mode)));$('#suggestions').replaceChildren(...c.prompts.map(p=>{const b=document.createElement('button');b.type='button';b.textContent=p+' ↗';b.onclick=()=>{$('#intent').value=p;prepare(p);};return b;}));}
function result(title,body,href,label,meta='Propuesta local · sin ejecución automática'){$('#result').innerHTML=`<article class="result-card"><div class="result-meta">${esc(meta)}</div><h3>${esc(title)}</h3>${body}<a href="${href}">${esc(label)} ↗</a></article>`;$('#result-section').hidden=false;$('#result-section').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'nearest'});}
function prepare(intent){
 // Integration boundary: replace guided local routing with POST /api/agent/requests.
 // Authenticate the user and company on the server. Never send secret keys from this file.
 // The server must return a validated proposal; approval and payment stay in their own flows.
 const text=intent.toLowerCase();
 if(mode==='daily'){const exporting=/export/.test(text),viewing=/ver|consult|revis/.test(text);result(exporting?'Tus gastos, listos para consultar.':viewing?'Una vista de tus gastos cotidianos.':'Registra lo que ya gastaste.',`<p>${exporting?'En el registro, filtra por mes y selecciona Exportar CSV.':viewing?'Consulta tus registros personales y sus totales separados por moneda.':'Anota concepto, proveedor, monto y fecha. El registro no realiza ni verifica pagos.'}</p><p>Los datos se conservan únicamente en este navegador.</p>`,'expenses.html?scope=shopping',exporting?'Abrir registro y exportar':viewing?'Consultar gastos':'Registrar gasto','Gastos reales registrados manualmente · almacenamiento local');return;}
 if(mode==='company'){
 if(/proveedor|pago|factura/.test(text)){result('Revisa antes de autorizar.', '<p>Abre las propuestas de la empresa para verificar proveedor, presupuesto y monto. La aprobación y el pago de esta demo son simulados.</p>','company.html#approvals','Revisar propuestas');return;}
 if(/presupuesto/.test(text)&&!/optim/.test(text)){result('Cada área, dentro de sus límites.','<p>Consulta los presupuestos y sus reservas antes de preparar nuevas acciones. Son cifras demostrativas del espacio empresarial.</p>','company.html#budgets','Ver presupuestos');return;}
 let state=initialState();try{const saved=JSON.parse(sessionStorage.getItem('reap-company-v1'));if(saved?.version===1&&Array.isArray(saved.budgets)&&Array.isArray(saved.requests))state=saved;}catch{}
 try{const plan=planCompany(state,{reserve:500000,capacity:3,horizon:7});result('Un plan para cuidar tus recursos.',`<p>Escenario demo: reserva de 5,000 USD, hasta 3 tareas y plazo de 7 días.</p>${plan.selected.length?`<ul>${plan.selected.map(a=>`<li>${esc(a.title)} · ${new Intl.NumberFormat('es-MX',{style:'currency',currency:'USD'}).format(a.cost/100)} estimados</li>`).join('')}</ul>`:'<p>No hay acciones nuevas elegibles con estos límites.</p>'}<p>${plan.deferred.length} opciones pospuestas. Pulsa «Ajustar y revisar en Empresa» para abrir el plan y crear propuestas.</p>`,'company.html?demo=resources#overview','Ajustar y revisar en Empresa');}catch{result('Revisemos los límites de la empresa.','<p>Abre el espacio empresarial para consultar el presupuesto disponible y ajustar la reserva del plan.</p>','company.html#overview','Abrir empresa');}return;
 }
 if(/pedido/.test(text)){result('Consulta tus pedidos de demostración.','<p>Revisa los pedidos completados en la sesión actual de Compras.</p>','shopping.html#orders','Ver pedidos');return;}
 if(!/aud[ií]fono|headphone/.test(text)){result('Encuentra una opción que se ajuste a ti.','<p>Entra al catálogo para explorar productos, comparar envíos y preparar una cotización de demostración.</p>','shopping.html#shop','Explorar catálogo');return;}
 const match=text.match(/(?:menos de|hasta|presupuesto(?: de)?|por)\s*\$?\s*(\d+(?:[.,]\d{1,2})?)/);const budget=match?Math.round(Number(match[1].replace(',','.'))*100):17000;
 try{const plan=planShopping({kind:'headphones',budget,horizon:7});const item=plan.selected[0];result(item?'Una opción dentro del presupuesto.':'Ampliemos las opciones.',item?`<p><strong>${esc(item.title)}</strong> con envío ${esc(item.shippingLabel)}.</p><p>Total simulado con envío e impuestos: <strong>${new Intl.NumberFormat('es-MX',{style:'currency',currency:'USD'}).format(item.cost/100)} USD</strong>.</p><p>Comparación: presupuesto ${new Intl.NumberFormat('es-MX',{style:'currency',currency:'USD'}).format(budget/100)} USD y plazo máximo de 7 días. En Compras, pulsa «Demo: comparar compras» para ajustar y seleccionar.</p>`:'<p>No encontramos audífonos dentro de ese presupuesto y plazo. Abre el catálogo para comparar otras opciones.</p>','shopping.html#shop','Comparar en Compras');}catch{result('Ajusta tu presupuesto.','<p>Indica un monto positivo en USD o explora las opciones del catálogo.</p>','shopping.html#shop','Explorar catálogo');}
}
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>changeMode(b.dataset.mode));$('#agent-form').onsubmit=e=>{e.preventDefault();const intent=$('#intent').value.trim();if(intent)prepare(intent);};changeMode('company');
